-- Native client sublimation socket patterns; SQL rows are the runtime authority.
CREATE TABLE native_sublimation_patterns (
 reference integer PRIMARY KEY CHECK(reference>0),
 item_level integer NOT NULL CHECK(item_level>=0),
 pattern_type text NOT NULL CHECK(pattern_type IN ('BASIC','EPIC','RELIC')),
 slot_colors smallint[] NOT NULL CHECK(cardinality(slot_colors) BETWEEN 1 AND 4),
 enabled boolean NOT NULL DEFAULT TRUE,
 client_jar_sha256 char(64) NOT NULL CHECK(client_jar_sha256 ~ '^[0-9a-f]{64}$'),
 CHECK (slot_colors <@ ARRAY[0,1,2,3,4]::smallint[])
);
CREATE INDEX native_sublimation_patterns_enabled ON native_sublimation_patterns(reference) WHERE enabled;
-- Replace the former empty JSON allowlist; native patterns live in the table above.
UPDATE settings SET value=value-'sublimation_rules' WHERE name='socket_enchantment_policy';
